-- Where the start tests keep the rows the functions return.
create temp table t260 (conversation_id uuid, user_message_id uuid, prior_no_knowledge integer);
grant all on t260 to service_role;

-- ===== grants, search_path, lock_timeout, SECURITY INVOKER =====
select is((select count(*)::int from pg_proc p where p.oid in ('public.get_chat_context(uuid)'::regprocedure, 'public.start_chat_turn(uuid,uuid,uuid,uuid,text)'::regprocedure, 'public.finish_chat_turn(uuid,uuid,uuid,uuid,uuid,uuid,text,text,text,text,text,jsonb)'::regprocedure, 'public.record_request_usage(uuid,uuid,text,text,text,integer,integer,numeric,integer)'::regprocedure, 'public.get_conversation_history(uuid,uuid,uuid,uuid,integer)'::regprocedure)
    and 'lock_timeout=2s' = any (p.proconfig) and 'search_path=""' = any (p.proconfig) and not p.prosecdef),
  5, 'proconfig: all five functions of migration 013 set lock_timeout = 2s and an empty search_path, and are SECURITY INVOKER');
select is((select count(*)::int from pg_proc p where p.oid in ('public.get_chat_context(uuid)'::regprocedure, 'public.start_chat_turn(uuid,uuid,uuid,uuid,text)'::regprocedure, 'public.finish_chat_turn(uuid,uuid,uuid,uuid,uuid,uuid,text,text,text,text,text,jsonb)'::regprocedure, 'public.record_request_usage(uuid,uuid,text,text,text,integer,integer,numeric,integer)'::regprocedure, 'public.get_conversation_history(uuid,uuid,uuid,uuid,integer)'::regprocedure)
    and has_function_privilege('service_role', p.oid, 'EXECUTE')
    and not has_function_privilege('anon', p.oid, 'EXECUTE') and not has_function_privilege('authenticated', p.oid, 'EXECUTE')
    and not exists (select 1 from aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a where a.grantee = 0)),
  5, 'grants: the five new functions are executable by service_role only (not anon, authenticated or PUBLIC)');
select ok(has_function_privilege('service_role', 'public.get_chat_context(uuid)', 'EXECUTE'), 'grants: service_role can EXECUTE get_chat_context');
select ok((select 'lock_timeout=2s' = any (proconfig) and 'search_path=""' = any (proconfig) and not prosecdef from pg_proc where oid = 'public.get_chat_context(uuid)'::regprocedure), 'proconfig: get_chat_context sets lock_timeout, an empty search_path and is SECURITY INVOKER');
select ok(has_function_privilege('service_role', 'public.start_chat_turn(uuid,uuid,uuid,uuid,text)', 'EXECUTE'), 'grants: service_role can EXECUTE start_chat_turn');
select ok((select 'lock_timeout=2s' = any (proconfig) and 'search_path=""' = any (proconfig) and not prosecdef from pg_proc where oid = 'public.start_chat_turn(uuid,uuid,uuid,uuid,text)'::regprocedure), 'proconfig: start_chat_turn sets lock_timeout, an empty search_path and is SECURITY INVOKER');
select ok(has_function_privilege('service_role', 'public.finish_chat_turn(uuid,uuid,uuid,uuid,uuid,uuid,text,text,text,text,text,jsonb)', 'EXECUTE'), 'grants: service_role can EXECUTE finish_chat_turn');
select ok((select 'lock_timeout=2s' = any (proconfig) and 'search_path=""' = any (proconfig) and not prosecdef from pg_proc where oid = 'public.finish_chat_turn(uuid,uuid,uuid,uuid,uuid,uuid,text,text,text,text,text,jsonb)'::regprocedure), 'proconfig: finish_chat_turn sets lock_timeout, an empty search_path and is SECURITY INVOKER');
