select lives_ok($q$insert into t260 select * from public.start_chat_turn('b0000001-0000-4000-8000-000000000260', 'a0000001-0000-4000-8000-000000000260', 'd0000001-0000-4000-8000-000000000260', null, '   hello world  ')$q$, 'start: a null conversation id starts a conversation (content padded with spaces)');
