select is((select prior_no_knowledge from t260), 0, 'start: a new conversation has prior_no_knowledge 0');
select is((select c.status || '/' || c.bot_id::text || '/' || c.visitor_session_id::text from public.conversations c where c.id = (select conversation_id from t260)), 'open/b0000001-0000-4000-8000-000000000260/a0000001-0000-4000-8000-000000000260', 'start: the new conversation is open and owned by the bot and the session');
select ok((select c.last_message_at is not null from public.conversations c where c.id = (select conversation_id from t260)), 'start: the new conversation has last_message_at');
select is((select m.role || '/' || m.content || '/' || m.status || '/' || m.request_id::text from public.messages m where m.id = (select user_message_id from t260)), 'user/hello world/complete/d0000001-0000-4000-8000-000000000260', 'start: the user message is stored trimmed with request_id = the run');
select is((select m.conversation_id from public.messages m where m.id = (select user_message_id from t260)), (select conversation_id from t260), 'start: the user message belongs to the returned conversation');
delete from t260;
select lives_ok($q$insert into t260 select * from public.start_chat_turn('b0000001-0000-4000-8000-000000000260', 'a0000001-0000-4000-8000-000000000260', 'd0000002-0000-4000-8000-000000000260', 'c0000001-0000-4000-8000-000000000260', 'second')$q$, 'start: an owned open conversation is reused (the run is only reserved)');
