-- ===== message_sources: members read the new columns as they read the old ones (copy of the 010 pattern) =====
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"22222222-0000-4000-8000-000000000260","aal":"aal2","role":"authenticated"}', true);
select is((select s.page_number || '/' || s.section from public.message_sources s where s.message_id = '83000001-0000-4000-8000-000000000260' and s.chunk_id = '90000001-0000-4000-8000-000000000260'), '3/Sec A', 'analyst: page_number and section are readable');
select cmp_ok((select count(*) from public.message_sources where page_number is not null)::int, '>=', 1, 'analyst: page_number can be filtered on');
select throws_ok($q$update public.message_sources set page_number = 5 where false$q$, '42501', null, 'analyst: updating page_number is denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"33333333-0000-4000-8000-000000000260","aal":"aal2","role":"authenticated"}', true);
select is((select s.page_number || '/' || s.section from public.message_sources s where s.message_id = '83000001-0000-4000-8000-000000000260' and s.chunk_id = '90000001-0000-4000-8000-000000000260'), '3/Sec A', 'admin: page_number and section are readable');
select cmp_ok((select count(*) from public.message_sources where page_number is not null)::int, '>=', 1, 'admin: page_number can be filtered on');
select throws_ok($q$update public.message_sources set page_number = 5 where false$q$, '42501', null, 'admin: updating page_number is denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"44444444-0000-4000-8000-000000000260","aal":"aal2","role":"authenticated"}', true);
select is((select s.page_number || '/' || s.section from public.message_sources s where s.message_id = '83000001-0000-4000-8000-000000000260' and s.chunk_id = '90000001-0000-4000-8000-000000000260'), '3/Sec A', 'owner: page_number and section are readable');
select cmp_ok((select count(*) from public.message_sources where page_number is not null)::int, '>=', 1, 'owner: page_number can be filtered on');
select throws_ok($q$update public.message_sources set page_number = 5 where false$q$, '42501', null, 'owner: updating page_number is denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"22222222-0000-4000-8000-000000000260","aal":"aal1","role":"authenticated"}', true);
select is((select count(*) from public.message_sources where message_id = '83000001-0000-4000-8000-000000000260')::int, 0, 'analyst at aal1: message_sources rows (and the new columns) stay hidden by RLS');
select throws_ok($q$update public.message_sources set page_number = 5 where false$q$, '42501', null, 'analyst at aal1: updating page_number is denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"11111111-0000-4000-8000-000000000260","aal":"aal2","role":"authenticated"}', true);
select is((select count(*) from public.message_sources where message_id = '83000001-0000-4000-8000-000000000260')::int, 0, 'nonmember: message_sources rows (and the new columns) stay hidden by RLS');
select throws_ok($q$update public.message_sources set page_number = 5 where false$q$, '42501', null, 'nonmember: updating page_number is denied');
reset role;
set local role anon;
select set_config('request.jwt.claims', '{"role":"anon"}', true);
select throws_ok($q$select page_number, section from public.message_sources$q$, '42501', null, 'anon: reading page_number and section is denied');
reset role;

-- ===== P7-D2: a question refused by moderation is marked blocked itself =====
insert into public.request_runs (id, bot_id, visitor_session_id, idempotency_key, request_hash, state) values
  ('d00000d1-0000-4000-8000-000000000260', 'b0000001-0000-4000-8000-000000000260', 'a0000001-0000-4000-8000-000000000260', '00000000-0000-4000-8000-0000000000d1', repeat('a', 64), 'running'),
  ('d00000d2-0000-4000-8000-000000000260', 'b0000001-0000-4000-8000-000000000260', 'a0000001-0000-4000-8000-000000000260', '00000000-0000-4000-8000-0000000000d2', repeat('a', 64), 'running');
set local role service_role;
select set_config('request.jwt.claims', '{"role":"service_role"}', true);
select set_config('t.d1', (select row(t.conversation_id, t.user_message_id)::text from public.start_chat_turn('b0000001-0000-4000-8000-000000000260', 'a0000001-0000-4000-8000-000000000260', 'd00000d1-0000-4000-8000-000000000260', null, 'a refused question') t), true);
select lives_ok(format($q$select public.finish_chat_turn('b0000001-0000-4000-8000-000000000260', 'a0000001-0000-4000-8000-000000000260', 'd00000d1-0000-4000-8000-000000000260', '830000d1-0000-4000-8000-000000000260', %L, %L, 'policy message', 'blocked', null, null, 'blocked', '[]'::jsonb)$q$,
  split_part(trim(both '()' from current_setting('t.d1')), ',', 1), split_part(trim(both '()' from current_setting('t.d1')), ',', 2)),
  'D2: finish with status blocked and handoff_reason blocked');
select is((select status from public.messages where id = split_part(trim(both '()' from current_setting('t.d1')), ',', 2)::uuid), 'blocked', 'D2: the refused question is marked blocked itself');
select set_config('t.d2', (select row(t.conversation_id, t.user_message_id)::text from public.start_chat_turn('b0000001-0000-4000-8000-000000000260', 'a0000001-0000-4000-8000-000000000260', 'd00000d2-0000-4000-8000-000000000260', null, 'an ordinary question') t), true);
select lives_ok(format($q$select public.finish_chat_turn('b0000001-0000-4000-8000-000000000260', 'a0000001-0000-4000-8000-000000000260', 'd00000d2-0000-4000-8000-000000000260', '830000d2-0000-4000-8000-000000000260', %L, %L, '', 'failed', null, null, 'unavailable', '[]'::jsonb)$q$,
  split_part(trim(both '()' from current_setting('t.d2')), ',', 1), split_part(trim(both '()' from current_setting('t.d2')), ',', 2)),
  'D2: finish with another outcome');
select is((select status from public.messages where id = split_part(trim(both '()' from current_setting('t.d2')), ',', 2)::uuid), 'complete', 'D2: any other outcome leaves the question complete');
reset role;

select * from finish();
rollback;
